SELECT
    COUNT(*) AS order_count,
    COALESCE(SUM(amount), 0) AS order_amount_cent,
    COALESCE(ROUND(AVG(amount)), 0) AS average_order_amount_cent
FROM tb_order
WHERE region_id = #{regionId}
  AND create_time >= #{start}
  AND create_time < #{endExclusive}
  AND status IN (1, 2)
